<script setup lang="ts">
import { reactive, ref } from "vue"; import { ElMessage } from "element-plus"; import { iamApi } from "../api/iam"; import type { Department, PermissionDefinition, Role, UserAccount } from "../types";
const tab=ref("departments");const departments=ref<Department[]>([]);const users=ref<UserAccount[]>([]);const roles=ref<Role[]>([]);const permissions=ref<PermissionDefinition[]>([]);const deptOpen=ref(false);const userOpen=ref(false);const roleOpen=ref(false);const editingDept=ref<Department|null>(null);const editingUser=ref<UserAccount|null>(null);const editingRole=ref<Role|null>(null);const deleteDept=ref<Department|null>(null);const deleteRole=ref<Role|null>(null);const resetUser=ref<UserAccount|null>(null);const resetPassword=ref("");const deptForm=reactive({name:"",parent_id:"",sort_order:0});const userForm=reactive({username:"",password:"",department_id:"",role_ids:[] as string[]});const roleForm=reactive({name:"",permission_codes:[] as string[]});
async function load(){const [d,u,r,p]=await Promise.all([iamApi.departments(),iamApi.users(),iamApi.roles(),iamApi.permissions()]);departments.value=d.items;users.value=u.items;roles.value=r.items;permissions.value=p.items}void load();
function openDept(row:Department|null=null){editingDept.value=row;Object.assign(deptForm,row?{name:row.name,parent_id:row.parent_id,sort_order:row.sort_order}:{name:"",parent_id:"",sort_order:0});deptOpen.value=true}
async function saveDept(){if(editingDept.value)await iamApi.updateDepartment(editingDept.value.department_id,deptForm);else await iamApi.createDepartment(deptForm);deptOpen.value=false;await load()}
async function removeDept(){if(deleteDept.value)await iamApi.deleteDepartment(deleteDept.value.department_id);deleteDept.value=null;await load()}
function openUser(row:UserAccount|null=null){editingUser.value=row;Object.assign(userForm,row?{username:row.username,password:"",department_id:row.department_id,role_ids:[...row.role_ids]}:{username:"",password:"",department_id:"",role_ids:[]});userOpen.value=true}
async function saveUser(){if(editingUser.value)await iamApi.setUserRoles(editingUser.value.user_id,userForm.role_ids);else await iamApi.createUser(userForm);userOpen.value=false;await load()}
async function resetUserPassword(){if(resetUser.value)await iamApi.resetPassword(resetUser.value.user_id,resetPassword.value);ElMessage.success("密码已重置");resetUser.value=null;resetPassword.value=""}
function openRole(row:Role|null=null){editingRole.value=row;Object.assign(roleForm,row?{name:row.name,permission_codes:[...row.permission_codes]}:{name:"",permission_codes:[]});roleOpen.value=true}
async function saveRole(){if(editingRole.value)await iamApi.setRolePermissions(editingRole.value.role_id,roleForm.permission_codes);else await iamApi.createRole(roleForm.name,roleForm.permission_codes);roleOpen.value=false;await load()}
async function removeRole(){if(deleteRole.value)await iamApi.deleteRole(deleteRole.value.role_id);deleteRole.value=null;await load()}
</script><template><el-card class="page-card" header="组织、账号与权限"><el-tabs v-model="tab"><el-tab-pane label="部门" name="departments"><el-button type="primary" class="toolbar" @click="openDept()">新增部门</el-button><el-table :data="departments"><el-table-column prop="department_id" label="部门 ID" width="180"/><el-table-column prop="name" label="名称"/><el-table-column prop="parent_id" label="上级" width="180"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="操作" width="220"><template #default="s"><el-button link @click="openDept(s.row)">编辑</el-button><el-button link @click="iamApi.setDepartmentStatus(s.row.department_id,s.row.status==='active'?'disabled':'active').then(load)">{{s.row.status==='active'?'停用':'启用'}}</el-button><el-button link type="danger" @click="deleteDept=s.row">删除</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="用户" name="users"><el-button type="primary" class="toolbar" @click="openUser()">新建用户</el-button><el-table :data="users"><el-table-column prop="username" label="用户名"/><el-table-column prop="department_id" label="部门"/><el-table-column label="角色"><template #default="s">{{s.row.role_ids.join(', ')}}</template></el-table-column><el-table-column prop="permission_version" label="权限版本" width="100"/><el-table-column prop="status" label="状态" width="90"/><el-table-column label="操作" width="280"><template #default="s"><el-button link @click="openUser(s.row)">分配角色</el-button><el-button link @click="resetUser=s.row;resetPassword=''">重置密码</el-button><el-button link @click="iamApi.setUserStatus(s.row.user_id,s.row.status==='active'?'disabled':'active').then(load)">{{s.row.status==='active'?'停用':'启用'}}</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="角色权限" name="roles"><el-button type="primary" class="toolbar" @click="openRole()">新建角色</el-button><el-table :data="roles"><el-table-column prop="name" label="角色"/><el-table-column prop="role_id" label="角色 ID"/><el-table-column prop="status" label="状态" width="90"/><el-table-column prop="permission_codes" label="权限数" width="100"><template #default="s">{{s.row.permission_codes.length}}</template></el-table-column><el-table-column label="操作" width="240"><template #default="s"><el-button link @click="openRole(s.row)">编辑权限</el-button><el-button link @click="iamApi.setRoleStatus(s.row.role_id,s.row.status==='active'?'disabled':'active').then(load)">{{s.row.status==='active'?'停用':'启用'}}</el-button><el-button link type="danger" @click="deleteRole=s.row">删除</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs><el-dialog v-model="deptOpen" :title="editingDept?'编辑部门':'新增部门'"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="deptForm.name"/></el-form-item><el-form-item label="上级部门"><el-select v-model="deptForm.parent_id" clearable style="width:100%"><el-option v-for="d in departments" :key="d.department_id" :label="d.name" :value="d.department_id"/></el-select></el-form-item><el-form-item label="排序"><el-input-number v-model="deptForm.sort_order"/></el-form-item></el-form><template #footer><el-button @click="deptOpen=false">取消</el-button><el-button type="primary" @click="saveDept">保存</el-button></template></el-dialog><el-dialog v-model="userOpen" :title="editingUser?'分配用户角色':'新建用户'"><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="userForm.username" :disabled="Boolean(editingUser)"/></el-form-item><el-form-item v-if="!editingUser" label="初始密码"><el-input v-model="userForm.password" type="password" show-password/></el-form-item><el-form-item v-if="!editingUser" label="部门"><el-select v-model="userForm.department_id" style="width:100%"><el-option v-for="d in departments" :key="d.department_id" :label="d.name" :value="d.department_id"/></el-select></el-form-item><el-form-item label="角色"><el-select v-model="userForm.role_ids" multiple style="width:100%"><el-option v-for="r in roles" :key="r.role_id" :label="r.name" :value="r.role_id"/></el-select></el-form-item></el-form><template #footer><el-button @click="userOpen=false">取消</el-button><el-button type="primary" @click="saveUser">保存</el-button></template></el-dialog><el-dialog v-model="roleOpen" :title="editingRole?'编辑角色权限':'新建角色'"><el-form label-position="top"><el-form-item label="角色名称"><el-input v-model="roleForm.name" :disabled="Boolean(editingRole)"/></el-form-item><el-form-item label="权限"><el-select v-model="roleForm.permission_codes" multiple filterable style="width:100%"><el-option v-for="p in permissions" :key="p.permission_code" :label="p.name+' ('+p.permission_code+')'" :value="p.permission_code"/></el-select></el-form-item></el-form><template #footer><el-button @click="roleOpen=false">取消</el-button><el-button type="primary" @click="saveRole">保存</el-button></template></el-dialog><el-dialog :model-value="Boolean(deleteDept)" title="删除部门" @close="deleteDept=null"><p>存在下级部门或成员时后端会拒绝删除。</p><template #footer><el-button @click="deleteDept=null">取消</el-button><el-button type="danger" @click="removeDept">删除</el-button></template></el-dialog><el-dialog :model-value="Boolean(resetUser)" title="重置密码" @close="resetUser=null"><el-input v-model="resetPassword" type="password" show-password placeholder="至少 8 位"/><template #footer><el-button @click="resetUser=null">取消</el-button><el-button type="primary" @click="resetUserPassword">确认重置</el-button></template></el-dialog><el-dialog :model-value="Boolean(deleteRole)" title="删除角色" @close="deleteRole=null"><p>角色仍被用户引用时后端会拒绝删除。</p><template #footer><el-button @click="deleteRole=null">取消</el-button><el-button type="danger" @click="removeRole">删除</el-button></template></el-dialog></el-card></template>
